// Fetches the one third-party asset this style needs: the bold serif used for titles.
// The original film used Georgia Bold, which ships with macOS and Windows but may not be redistributed,
// so it is copied from the system at build time and never committed. Without it (or with --ofl),
// Gelasio, an SIL Open Font License serif drawn to Georgia's metrics, is downloaded from Google Fonts.
// There is no music to fetch: the ambience bed is generated by scripts/generate-ambience.mjs.
//
//   node fetch-assets.mjs         Georgia Bold from the system, else Gelasio
//   node fetch-assets.mjs --ofl   always Gelasio (fully redistributable)
import { copyFileSync, existsSync, mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('.', import.meta.url));
const fontsDir = join(ROOT, 'assets', 'fonts');
const out = join(fontsDir, 'title-serif.ttf');
mkdirSync(fontsDir, { recursive: true });

const systemGeorgiaBold = [
  '/System/Library/Fonts/Supplemental/Georgia Bold.ttf',
  '/Library/Fonts/Georgia Bold.ttf',
  'C:\\Windows\\Fonts\\georgiab.ttf',
  '/usr/share/fonts/truetype/msttcorefonts/Georgia_Bold.ttf',
  '/usr/share/fonts/truetype/msttcorefonts/georgiab.ttf',
];
const GELASIO = 'https://raw.githubusercontent.com/google/fonts/main/ofl/gelasio/Gelasio%5Bwght%5D.ttf';

const found = process.argv.includes('--ofl') ? null : systemGeorgiaBold.find((p) => existsSync(p));
if (found) {
  copyFileSync(found, out);
  writeFileSync(join(fontsDir, 'SOURCE.txt'), 'title-serif.ttf is Georgia Bold copied from this machine\'s system fonts. Do not commit or redistribute it.\n');
  console.log('Title font: Georgia Bold copied from the system fonts');
} else {
  const r = await fetch(GELASIO, { signal: AbortSignal.timeout(60000) });
  if (!r.ok) throw new Error(`Gelasio download failed: HTTP ${r.status}`);
  const buf = Buffer.from(await r.arrayBuffer());
  if (buf.length < 50000) throw new Error('Gelasio download looks truncated');
  writeFileSync(out, buf);
  writeFileSync(join(fontsDir, 'SOURCE.txt'), `title-serif.ttf is Gelasio (variable, SIL Open Font License 1.1) from ${GELASIO}\n`);
  console.log(`Title font: Gelasio (OFL) downloaded, ${(buf.length / 1024).toFixed(0)} KB`);
}
